V='20261022-xinnian-1';SH='../../../shared/lesson-v1/';TOP='../../../../../'
def page(title,body,scripts=''):
 return f'<!doctype html><html lang="zh-SG"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} · 华文通</title><link rel="stylesheet" href="{SH}style.css?v={V}"><link rel="stylesheet" href="lesson.css?v={V}"></head><body><header class="site-header"><a href="{TOP}index.html#1/texts"><img src="{TOP}assets/huawentong-logo.png" alt="华文通"></a><span>{L["label"]}</span></header>{body}{scripts}</body></html>'
