def nav():return '<nav class="nav"><a class="btn" href="index.html">课文主页</a><a class="btn" href="reading.html">互动学习</a><a class="btn" href="comics.html">漫画回读</a></nav>'
body='<nav class="nav"><a class="btn" href="index.html">主页</a><button data-view="read">读文</button><button data-view="lesson1">本课问题</button><button data-view="review">检查</button><button id="wordList">词语本</button></nav><details class="identity-banner"><summary>姓名与班级</summary><div id="topIdentity" class="identity"></div></details><main><p id="saveState" class="muted" role="status"></p><div id="readTask" class="workspace"><article id="source" class="paper"></article><section id="activity" class="paper"></section></div><section id="review" class="paper" hidden></section><dialog id="dialog"><button id="dialogClose" class="dialog-close">关闭</button><div id="dialogContent"></div></dialog><dialog id="wordDialog"><button id="wordDialogClose" class="dialog-close">关闭</button><div id="wordDialogContent"></div></dialog></main>'
scripts=''.join(script(f) for f in ['content.js','lexicon.js',SH+'catalog.js',SH+'wordbook.js',SH+'app.js',SH+'identity.js',SH+'summary-table.js'])
(R/'reading.html').write_text(page(L['title']+' · 互动学习',body,scripts))
body=f'<main><p class="crumb">中一高级华文 / 单元二 / 生活空间</p><section class="hero"><div><h1>{L["title"]}</h1><p class="lead">怎样迎新年？<br>不同做法，寄托什么愿望？</p><div class="actions"><a class="btn primary" href="reading.html">开始／继续学习</a><a class="btn" href="reading.html#words">我的词语本</a></div><p class="muted">一课时 · 原文与漫画 · 课本问题</p></div><div class="cover-panel"><img src="assets/comic1.png" alt="世界各地的新年风俗原漫画第一页"></div></section><div class="resource-grid"><a class="paper" href="reading.html#lesson1"><h2>本课问题</h2><p>整理信息 · 比较愿望 · 查找分享</p></a><a class="paper" href="comics.html"><h2>漫画回读</h2><p>完整原文与三页原漫画</p></a><a class="paper" href="teacher.html"><h2>教师资料</h2><p>课件 · 教案答案 · 在线投影 · 下载</p></a></div></main>'
(R/'index.html').write_text(page(L['title'],body))
body=nav()+'<main><h1>漫画回读</h1><p>按课文顺序阅读。图画帮助理解，答案依据回到原文。</p>'
for i,p in enumerate(L['paragraphs']):body+=f'<section class="paper reread"><h2>第{["一","二","三","四","五"][i]}段 · {L["paragraphLabels"][i]}</h2><p class="source-text">{p}</p></section>'
body+='<section class="paper"><h2>课本小知识</h2><p>元旦：阳历1月1日。春节：农历正月初一。农历新年也叫“春节”。</p></section>'
for i in range(1,4):body+=f'<figure class="whole-comic"><img src="assets/comic{i}.png" alt="原漫画第{i}页"><figcaption>原漫画第{i}页</figcaption></figure>'
body+='</main>';(R/'comics.html').write_text(page('漫画回读',body))
body='<nav class="nav"><a class="btn" href="teacher.html">教师资料</a><button id="prev">上一页</button><select id="slideSelect" aria-label="选择课件页"></select><button id="next">下一页</button><button id="full">全屏</button><span id="counter"></span></nav><main><div id="projector"><img id="slideImage" alt="教学课件"></div><details><summary>教师提示</summary><p id="notes"></p></details></main>'
(R/'projection.html').write_text(page('在线投影',body,script('projection.js')))
body=nav()+'<main><h1>教师资料</h1><p class="lead">世界各地的新年风俗</p><p>一课时，按50分钟安排。8个核心任务，2处书面作答。</p><div class="actions"><a class="btn primary" href="projection.html">在线投影</a><a class="btn" href="downloads/xinnian-fengsu.pptx" download>可编辑PPT</a><a class="btn" href="downloads/teacher-guide.docx" download>教师流程与答案</a><button class="btn" id="downloadOffline">离线学习包</button><button class="btn" id="downloadPack">整套下载</button></div><p id="packStatus" role="status"></p><details><summary>字体与可编辑源文件</summary><div class="actions"><a class="btn" href="downloads/fonts.zip" download>课件字体</a><a class="btn" href="downloads/source.zip" download>源文件</a></div></details>'
body+='<section class="paper"><h2>教学目标</h2><ol>'+''.join('<li>'+E(g)+'</li>' for g in L['goals'])+'</ol><h2>课堂流程</h2><table><thead><tr><th>环节</th><th>分钟</th><th>教师安排</th></tr></thead><tbody>'+''.join('<tr><th>'+n+'</th><td>'+str(m)+'</td><td>'+d+'</td></tr>' for n,m,d in L['flow'])+'</tbody></table></section>'
body+='<section class="paper"><h2>原题与教学处理</h2><p>课本第二题的“象征意义”是共同栏：前五步先辨认各地具体寓意，第六步再填写共同愿望。第一题五组搭配与第三题检索分享均完整保留。新增追问已标为教师补充。</p><p>原文以地区分块，网页按原顺序编为第1—5段，便于定位。三张原漫画不改内容：第1段对应1—3格，第2段4—6格，第3段7—9格，第4段10—12格，第5段13—16格；17—18格为课本小知识，整页回读保留。</p><p>按课文理解传统风俗，不把教材概括说成当代每个人的实际做法。抛瓶罐、泼水及碎碗碟只作文化阅读，不安排仿做。</p></section>'
for t in L['tasks']:
 body+='<section class="paper answer-section"><h2>'+E(t['title'])+'</h2><p class="muted">'+E(t['role'])+'；'+E(t['source'])+'</p>'+''.join('<p class="question">'+E(q)+'</p>' for q in t['questions'])+'<h3>原文证据</h3><p class="kai">'+E(t['evidenceText'])+'</p><h3>参考答案</h3><p class="model">'+E(t['answer']).replace('\n','<br>')+'</p><h3>解释与接受范围</h3><p>'+E(t['explain'])+'</p><h3>常见失分</h3><p>'+E(t['reject'])+'</p><h3>参考评价</h3><p>'+E(t['scoreGuide'])+'</p><details><summary>分层提示</summary><ol>'+''.join('<li>'+E(h)+'</li>' for h in t['hints'])+'</ol></details></section>'
body+='<section class="paper"><h2>使用说明</h2><p>作答保存在同设备、同浏览器，保留首次答案、尝试与订正。可填写姓名、班级、学号并导出JSON、CSV或文字记录。尚未接入教师自动收件或成绩上传。</p><p>词语本沿用华文通共享格式，可按年级、单元、课文筛选，支持导入导出。未知词可以收藏，释义标为待补充。离线与在线页面的记录分开。重置本课不删个人词语本。</p><p>客观任务6组：五地信息各两项＋词语搭配五项，共15个客观检查点。网页“首次全部答对率”以6组为分母，不等同于逐空得分，也不代表独立掌握；西班牙为教师示范，古巴为共同完成。两道书面题由教师覆核，参考4点＋4点，不并入自动分数。</p><p>在线投影与PPT页序相同。课件文字均可编辑；本机字体不足时，可安装所附字体或使用在线投影。教师页公开含答案，不作为身份保护。</p><h3>第三题资料来源</h3><a href="https://www.japan.travel/en/sg/story/new-year-food-traditions/" target="_blank" rel="noopener">日本国家旅游局：New Year food traditions</a><p>2018年12月21日发布，2026年10月22日核对。示范只用“新年前夜吃荞麦面，以细长面条象征长寿”，不讨论有争议的起源年代。</p></section></main>'
(R/'teacher.html').write_text(page('教师资料',body,script('pack.js')))
